pub const MirrorNeuronSystem = struct {
    allocator: Allocator,
    mirror_neurons: []MirrorNeuron,
    self_action_patterns: []f32,
    observed_action_patterns: []f32,
    shared_representations: []f32,
    empathy_level: f32,
    cmni_score: f32,
    perception_action_coupling: f32,

    pub fn init(allocator: Allocator) !MirrorNeuronSystem {
        const neuron_count: usize = 256;
        const pattern_dim: usize = 512;

        var neurons = try allocator.alloc(MirrorNeuron, neuron_count);
        for (neurons) |*n| {
            n.* = MirrorNeuron.init();
        }

        return MirrorNeuronSystem{
            .allocator = allocator,
            .mirror_neurons = neurons,
            .self_action_patterns = try allocator.alloc(f32, pattern_dim),
            .observed_action_patterns = try allocator.alloc(f32, pattern_dim),
            .shared_representations = try allocator.alloc(f32, pattern_dim),
            .empathy_level = 0.0,
            .cmni_score = 0.0,
            .perception_action_coupling = 0.7,
        };
    }

    pub fn deinit(self: *MirrorNeuronSystem) void {
        self.allocator.free(self.mirror_neurons);
        self.allocator.free(self.self_action_patterns);
        self.allocator.free(self.observed_action_patterns);
        self.allocator.free(self.shared_representations);
    }

    pub fn processObservationAction(self: *MirrorNeuronSystem, observation: []const f32, action: []const f32) !MirrorOutput {
        try self.updateObservedPatterns(observation);
        try self.updateSelfPatterns(action);

        for (self.mirror_neurons, 0..) |*neuron, idx| {
            const obs_input = if (idx < observation.len) observation[idx] else 0.0;
            const act_input = if (idx < action.len) action[idx] else 0.0;

            neuron.updateActivation(obs_input, act_input, self.perception_action_coupling);
        }

        try self.computeSharedRepresentations();
        self.cmni_score = try self.computeCMNI();
        self.empathy_level = self.computeEmpathy();

        return MirrorOutput{
            .empathy_level = self.empathy_level,
            .cmni_score = self.cmni_score,
            .shared_activation = self.shared_representations[0],
        };
    }

    fn updateObservedPatterns(self: *MirrorNeuronSystem, observation: []const f32) !void {
        const copy_len = @min(observation.len, self.observed_action_patterns.len);
        for (0..copy_len) |i| {
            self.observed_action_patterns[i] = observation[i];
        }
    }

    fn updateSelfPatterns(self: *MirrorNeuronSystem, action: []const f32) !void {
        const copy_len = @min(action.len, self.self_action_patterns.len);
        for (0..copy_len) |i| {
            self.self_action_patterns[i] = action[i];
        }
    }

    fn computeSharedRepresentations(self: *MirrorNeuronSystem) !void {
        for (self.shared_representations, 0..) |*rep, i| {
            const self_val = self.self_action_patterns[i];
            const obs_val = self.observed_action_patterns[i];
            rep.* = (self_val + obs_val) * 0.5;
        }
    }

    fn computeCMNI(self: *MirrorNeuronSystem) !f32 {
        var overlap_sum: f32 = 0.0;
        var self_norm: f32 = 0.0;
        var obs_norm: f32 = 0.0;

        for (self.self_action_patterns, self.observed_action_patterns) |s, o| {
            overlap_sum += s * o;
            self_norm += s * s;
            obs_norm += o * o;
        }

        const denominator = @sqrt(self_norm * obs_norm);
        if (denominator > 0.0001) {
            return overlap_sum / denominator;
        }
        return 0.0;
    }

    fn computeEmpathy(self: *MirrorNeuronSystem) f32 {
        var activation_sum: f32 = 0.0;
        for (self.mirror_neurons) |neuron| {
            activation_sum += neuron.mirror_activation;
        }
        return activation_sum / @as(f32, @floatFromInt(self.mirror_neurons.len));
    }
};

pub const MirrorNeuron = struct {
    self_activation: f32,
    observed_activation: f32,
    mirror_activation: f32,
    coupling_strength: f32,

    pub fn init() MirrorNeuron {
        return MirrorNeuron{
            .self_activation = 0.0,
            .observed_activation = 0.0,
            .mirror_activation = 0.0,
            .coupling_strength = 0.8,
        };
    }

    pub fn updateActivation(self: *MirrorNeuron, obs_input: f32, self_input: f32, coupling: f32) void {
        self.self_activation = sigmoid(self_input);
        self.observed_activation = sigmoid(obs_input);

        self.mirror_activation = coupling * @min(self.self_activation, self.observed_activation) + (1.0 - coupling) * @max(self.self_activation, self.observed_activation);
    }
};

pub const LatentWorldModel = struct {
    allocator: Allocator,
    latent_states: []f32,
    action_representations: []f32,
    transition_model: []f32,
    state_dim: usize,
    action_dim: usize,
    temporal_depth: usize,

    pub fn init(allocator: Allocator) !LatentWorldModel {
        const state_dim: usize = 128;
        const action_dim: usize = 64;
        const depth: usize = 16;

        return LatentWorldModel{
            .allocator = allocator,
            .latent_states = try allocator.alloc(f32, state_dim * depth),
            .action_representations = try allocator.alloc(f32, action_dim * depth),
            .transition_model = try allocator.alloc(f32, state_dim * state_dim),
            .state_dim = state_dim,
            .action_dim = action_dim,
            .temporal_depth = depth,
        };
    }

    pub fn deinit(self: *LatentWorldModel) void {
        self.allocator.free(self.latent_states);
        self.allocator.free(self.action_representations);
        self.allocator.free(self.transition_model);
    }

    pub fn predictLatentAction(self: *LatentWorldModel, observation: []const f32, temporal_sequence: []const f32) !LatentOutput {
        try self.encodeObservation(observation);
        try self.inferLatentActions(temporal_sequence);

        const state_repr = try self.allocator.alloc(f32, self.state_dim);
        @memcpy(state_repr, self.latent_states[0..self.state_dim]);

        return LatentOutput{
            .state_representation = state_repr,
            .predicted_next_state = self.latent_states[self.state_dim],
        };
    }

    fn encodeObservation(self: *LatentWorldModel, observation: []const f32) !void {
        for (1..self.temporal_depth) |t| {
            const src_start = (t - 1) * self.state_dim;
            const dst_start = t * self.state_dim;
            @memcpy(self.latent_states[dst_start..dst_start + self.state_dim], self.latent_states[src_start..src_start + self.state_dim]);
        }

        for (0..self.state_dim) |i| {
            if (i < observation.len) {
                self.latent_states[i] = observation[i];
            } else {
                self.latent_states[i] = 0.0;
            }
        }
    }

    fn inferLatentActions(self: *LatentWorldModel, temporal_sequence: []const f32) !void {
        for (0..@min(self.temporal_depth - 1, temporal_sequence.len)) |t| {
            const current_state = self.latent_states[t * self.state_dim..(t + 1) * self.state_dim];
            const next_state = self.latent_states[(t + 1) * self.state_dim..(t + 2) * self.state_dim];

            for (0..self.action_dim) |a| {
                var action_score: f32 = 0.0;
                for (0..@min(self.state_dim, current_state.len)) |s| {
                    action_score += current_state[s] * next_state[s % next_state.len];
                }
                self.action_representations[t * self.action_dim + a] = sigmoid(action_score);
            }
        }
    }

    pub fn consolidateLatentRepresentations(self: *LatentWorldModel) !void {
        for (0..self.state_dim * self.state_dim) |i| {
            self.transition_model[i] *= 0.99;
        }

        for (0..self.temporal_depth - 1) |t| {
            const current = self.latent_states[t * self.state_dim..(t + 1) * self.state_dim];
            const next = self.latent_states[(t + 1) * self.state_dim..(t + 2) * self.state_dim];

            for (0..self.state_dim) |i| {
                for (0..self.state_dim) |j| {
                    const idx = i * self.state_dim + j;
                    self.transition_model[idx] += 0.01 * current[i] * next[j];
                }
            }
        }
    }
};

pub const SchemaActiveInference = struct {
    allocator: Allocator,
    schemas: []Schema,
    free_energy: f32,
    prediction_error: f32,
    prior_beliefs: []f32,
    posterior_beliefs: []f32,
    sensory_precision: f32,

    pub fn init(allocator: Allocator) !SchemaActiveInference {
        const num_schemas: usize = 32;
        const belief_dim: usize = 256;

        var schemas = try allocator.alloc(Schema, num_schemas);
        for (schemas, 0..) |*s, i| {
            s.* = try Schema.init(allocator, i);
        }

        return SchemaActiveInference{
            .allocator = allocator,
            .schemas = schemas,
            .free_energy = 0.0,
            .prediction_error = 0.0,
            .prior_beliefs = try allocator.alloc(f32, belief_dim),
            .posterior_beliefs = try allocator.alloc(f32, belief_dim),
            .sensory_precision = 1.0,
        };
    }

    pub fn deinit(self: *SchemaActiveInference) void {
        for (self.schemas) |*s| {
            s.deinit();
        }
        self.allocator.free(self.schemas);
        self.allocator.free(self.prior_beliefs);
        self.allocator.free(self.posterior_beliefs);
    }

    pub fn inferSchema(self: *SchemaActiveInference, observation: []const f32, latent_state: []const f32) !SchemaOutput {
        for (self.schemas) |*schema| {
            schema.activation = try schema.computeActivation(observation, latent_state);
        }

        try self.updateBeliefs(observation);
        self.free_energy = try self.computeFreeEnergy();

        const active = try self.getActiveSchemas();
        const coherence = self.computeSchemaCoherence();

        return SchemaOutput{
            .active_schemas = active,
            .free_energy_minimization = self.free_energy,
            .schema_coherence = coherence,
        };
    }

    fn updateBeliefs(self: *SchemaActiveInference, observation: []const f32) !void {
        @memcpy(self.prior_beliefs, self.posterior_beliefs);

        for (self.posterior_beliefs, 0..) |*belief, i| {
            const obs = if (i < observation.len) observation[i] else 0.0;
            const prior = self.prior_beliefs[i];

            const prediction_error_i = obs - prior;
            belief.* = prior + 0.1 * self.sensory_precision * prediction_error_i;
        }
    }

    fn computeFreeEnergy(self: *SchemaActiveInference) !f32 {
        var energy: f32 = 0.0;

        for (self.prior_beliefs, self.posterior_beliefs) |prior, post| {
            const kl_term = if (post > 0.0001 and prior > 0.0001) post * @log(post / prior) else 0.0;
            energy += kl_term;
        }

        for (self.schemas) |schema| {
            energy -= schema.activation * 0.1;
        }

        return energy;
    }

    fn getActiveSchemas(self: *SchemaActiveInference) ![]usize {
        var active_count: usize = 0;
        for (self.schemas) |schema| {
            if (schema.activation > 0.5) active_count += 1;
        }

        var active = try self.allocator.alloc(usize, active_count);
        var idx: usize = 0;
        for (self.schemas, 0..) |schema, i| {
            if (schema.activation > 0.5) {
                active[idx] = i;
                idx += 1;
            }
        }

        return active;
    }

    fn computeSchemaCoherence(self: *SchemaActiveInference) f32 {
        var max_activation: f32 = 0.0;
        var total_activation: f32 = 0.0;

        for (self.schemas) |schema| {
            total_activation += schema.activation;
            if (schema.activation > max_activation) {
                max_activation = schema.activation;
            }
        }

        if (total_activation > 0.0001) {
            return max_activation / total_activation;
        }
        return 0.0;
    }

    pub fn integrateInsight(self: *SchemaActiveInference, insight: []const f32) !void {
        const target_schema_idx = self.schemas.len / 2;
        try self.schemas[target_schema_idx].integrateNewKnowledge(insight);

        self.sensory_precision *= 1.05;
    }

    pub fn updateSchemaHierarchy(self: *SchemaActiveInference) !void {
        for (self.schemas) |*schema| {
            schema.consolidate();
        }
    }
};

pub const Schema = struct {
    allocator: Allocator,
    id: usize,
    pattern: []f32,
    activation: f32,
    stability: f32,

    pub fn init(allocator: Allocator, id: usize) !Schema {
        const pattern_size: usize = 128;
        var pattern = try allocator.alloc(f32, pattern_size);

        var prng = std.rand.DefaultPrng.init(@intCast(id * 1000));
        const random = prng.random();
        for (pattern) |*p| {
            p.* = random.float(f32);
        }

        return Schema{
            .allocator = allocator,
            .id = id,
            .pattern = pattern,
            .activation = 0.0,
            .stability = 0.5,
        };
    }

    pub fn deinit(self: *Schema) void {
        self.allocator.free(self.pattern);
    }

    pub fn computeActivation(self: *Schema, observation: []const f32, latent: []const f32) !f32 {
        var match_score: f32 = 0.0;

        for (self.pattern, 0..) |p, i| {
            const obs = if (i < observation.len) observation[i] else 0.0;
            const lat = if (i < latent.len) latent[i] else 0.0;
            match_score += p * (obs + lat) * 0.5;
        }

        return sigmoid(match_score / @as(f32, @floatFromInt(self.pattern.len)));
    }

    pub fn integrateNewKnowledge(self: *Schema, knowledge: []const f32) !void {
        const learning_rate = 0.05;
        for (self.pattern, 0..) |*p, i| {
            const k = if (i < knowledge.len) knowledge[i] else 0.0;
            p.* = p.* * (1.0 - learning_rate) + k * learning_rate;
        }
        self.stability += 0.1;
    }

    pub fn consolidate(self: *Schema) void {
        self.stability = @min(1.0, self.stability * 1.01);
    }
};

pub const Metaplasticity = struct {
    allocator: Allocator,
    plasticity_threshold: f32,
    threshold_history: []f32,
    bcm_threshold: f32,
    activity_window: []f32,
    current_state: f32,

    pub fn init(allocator: Allocator) !Metaplasticity {
        const history_len: usize = 256;

        return Metaplasticity{
            .allocator = allocator,
            .plasticity_threshold = 0.5,
            .threshold_history = try allocator.alloc(f32, history_len),
            .bcm_threshold = 0.5,
            .activity_window = try allocator.alloc(f32, 100),
            .current_state = 1.0,
        };
    }

    pub fn deinit(self: *Metaplasticity) void {
        self.allocator.free(self.threshold_history);
        self.allocator.free(self.activity_window);
    }

    pub fn getCurrentState(self: *Metaplasticity) f32 {
        return self.current_state;
    }

    pub fn computeHomeostaticFactor(self: *Metaplasticity) f32 {
        var avg_activity: f32 = 0.0;
        for (self.activity_window) |a| {
            avg_activity += a;
        }
        avg_activity /= @as(f32, @floatFromInt(self.activity_window.len));

        const target_activity: f32 = 0.15;
        const deviation = avg_activity - target_activity;

        return 1.0 - deviation * 0.5;
    }

    pub fn updatePlasticityThreshold(self: *Metaplasticity, dopamine: f32, activity: f32) !void {
        for (1..self.activity_window.len) |i| {
            self.activity_window[self.activity_window.len - i] = self.activity_window[self.activity_window.len - i - 1];
        }
        self.activity_window[0] = activity;

        const avg_activity = blk: {
            var sum: f32 = 0.0;
            for (self.activity_window) |a| sum += a;
            break :blk sum / @as(f32, @floatFromInt(self.activity_window.len));
        };

        self.bcm_threshold = avg_activity * avg_activity;

        self.plasticity_threshold += 0.01 * (dopamine - 0.5);
        self.plasticity_threshold = @max(0.1, @min(0.9, self.plasticity_threshold));

        if (activity > self.bcm_threshold) {
            self.current_state = 1.2;
        } else {
            self.current_state = 0.8;
        }

        for (1..self.threshold_history.len) |i| {
            self.threshold_history[self.threshold_history.len - i] = self.threshold_history[self.threshold_history.len - i - 1];
        }
        self.threshold_history[0] = self.plasticity_threshold;
    }
};

pub const TemporalErrorAccumulator = struct {
    allocator: Allocator,
    error_buffer: []f32,
    accumulated_value: f32,
    time_independent_encoding: []f32,
    cortical_assembly: []NeuronAssembly,

    pub fn init(allocator: Allocator) !TemporalErrorAccumulator {
        const buffer_size: usize = 512;
        const assembly_size: usize = 64;

        var assemblies = try allocator.alloc(NeuronAssembly, assembly_size);
        for (assemblies) |*a| {
            a.* = NeuronAssembly.init();
        }

        return TemporalErrorAccumulator{
            .allocator = allocator,
            .error_buffer = try allocator.alloc(f32, buffer_size),
            .accumulated_value = 0.0,
            .time_independent_encoding = try allocator.alloc(f32, buffer_size),
            .cortical_assembly = assemblies,
        };
    }

    pub fn deinit(self: *TemporalErrorAccumulator) void {
        self.allocator.free(self.error_buffer);
        self.allocator.free(self.time_independent_encoding);
        self.allocator.free(self.cortical_assembly);
    }

    pub fn accumulateError(self: *TemporalErrorAccumulator, error: f32, time_step: usize) !void {
        const idx = time_step % self.error_buffer.len;
        self.error_buffer[idx] = error;

        self.accumulated_value += error;

        for (self.cortical_assembly, 0..) |*assembly, i| {
            const temporal_position = @as(f32, @floatFromInt((time_step + i) % self.cortical_assembly.len));
            assembly.activity += error * @exp(-temporal_position / 10.0);
        }

        self.time_independent_encoding[idx] = self.computeTimeIndependentSignal(error);
    }

    fn computeTimeIndependentSignal(self: *TemporalErrorAccumulator, error: f32) f32 {
        _ = self;
        return error * error;
    }

