pub const HabituationSensitization = struct {
    allocator: Allocator,
    habituation_level: f32,
    sensitization_level: f32,
    stimulus_history: []f32,
    response_magnitude: f32,
    s_r_system_state: f32,
    state_system_readiness: f32,

    pub fn init(allocator: Allocator) !HabituationSensitization {
        const history_len: usize = 256;

        return HabituationSensitization{
            .allocator = allocator,
            .habituation_level = 0.0,
            .sensitization_level = 0.0,
            .stimulus_history = try allocator.alloc(f32, history_len),
            .response_magnitude = 1.0,
            .s_r_system_state = 1.0,
            .state_system_readiness = 0.5,
        };
    }

    pub fn deinit(self: *HabituationSensitization) void {
        self.allocator.free(self.stimulus_history);
    }

    pub fn processStimulus(self: *HabituationSensitization, stimulus: []const f32, intensity: f32) !HabituationOutput {
        try self.updateStimulusHistory(stimulus);

        const repetition_count = self.countRecentRepetitions();
        self.habituation_level += 0.01 * @as(f32, @floatFromInt(repetition_count));
        self.habituation_level = @min(1.0, self.habituation_level);

        if (intensity > 0.8) {
            self.sensitization_level += 0.05 * intensity;
            self.sensitization_level = @min(1.0, self.sensitization_level);
            self.state_system_readiness += 0.1;
        }

        self.s_r_system_state = 1.0 - self.habituation_level;

        self.response_magnitude = self.s_r_system_state * (1.0 + self.sensitization_level * self.state_system_readiness);

        self.habituation_level *= 0.99;
        self.sensitization_level *= 0.98;

        return HabituationOutput{
            .response_magnitude = self.response_magnitude,
            .habituation_degree = self.habituation_level,
            .sensitization_degree = self.sensitization_level,
        };
    }

    fn updateStimulusHistory(self: *HabituationSensitization, stimulus: []const f32) !void {
        const hash_value = hashInput(stimulus);

        for (1..self.stimulus_history.len) |i| {
            self.stimulus_history[self.stimulus_history.len - i] = self.stimulus_history[self.stimulus_history.len - i - 1];
        }
        self.stimulus_history[0] = hash_value;
    }

    fn countRecentRepetitions(self: *HabituationSensitization) usize {
        const current = self.stimulus_history[0];
        var count: usize = 0;
        const window: usize = 10;

        for (1..@min(window, self.stimulus_history.len)) |i| {
            if (@abs(self.stimulus_history[i] - current) < 0.1) {
                count += 1;
            }
        }

        return count;
    }
};

pub const InsightLearning = struct {
    allocator: Allocator,
    problem_representations: []ProblemState,
    insight_threshold: f32,
    incubation_time: usize,
    current_time: usize,

    pub fn init(allocator: Allocator) !InsightLearning {
        const max_problems: usize = 16;

        var problems = try allocator.alloc(ProblemState, max_problems);
        for (problems) |*p| {
            p.* = ProblemState.init();
        }

        return InsightLearning{
            .allocator = allocator,
            .problem_representations = problems,
            .insight_threshold = 0.7,
            .incubation_time = 100,
            .current_time = 0,
        };
    }

    pub fn deinit(self: *InsightLearning) void {
        for (self.problem_representations) |*p| {
            p.deinit(self.allocator);
        }
        self.allocator.free(self.problem_representations);
    }

    pub fn detectAhaCondition(self: *InsightLearning, accumulated_error: f32, schema_coherence: f32) bool {
        self.current_time += 1;

        const high_error = accumulated_error > 5.0;
        const coherent_schema = schema_coherence > self.insight_threshold;
        const sufficient_incubation = (self.current_time % self.incubation_time) == 0;

        return high_error and coherent_schema and sufficient_incubation;
    }

    pub fn triggerInsight(self: *InsightLearning, active_schemas: []const usize) !InsightOutput {
        const problem_idx = self.current_time % self.problem_representations.len;
        var problem = &self.problem_representations[problem_idx];

        const solution = try self.allocator.alloc(f32, 128);

        for (solution, 0..) |*s, i| {
            var combined: f32 = 0.0;
            for (active_schemas) |schema_id| {
                combined += @as(f32, @floatFromInt(schema_id)) * @as(f32, @floatFromInt(i + 1));
            }
            s.* = sigmoid(combined / 100.0);
        }

        problem.solved = true;
        problem.solution_quality = 0.9;

        return InsightOutput{
            .solution_representation = solution,
            .aha_moment = true,
            .solution_quality = problem.solution_quality,
        };
    }

    pub fn pruneInsightCandidates(self: *InsightLearning) !void {
        for (self.problem_representations) |*problem| {
            if (problem.solved) {
                problem.solution_quality *= 0.95;
            }
        }
    }
};

