fn sigmoid(x: f32) f32 {
    return 1.0 / (1.0 + @exp(-x));
}

fn hashInput(input: []const f32) f32 {
    var hash: f32 = 0.0;
    for (input, 0..) |val, i| {
        hash += val * @as(f32, @floatFromInt(i + 1));
    }
    return @mod(hash, 1.0);
}

