pub const NeurobiologicalLearningSystem = struct {
    persistent_allocator: Allocator,
    scratch_arena: ArenaAllocator,
    scratch_allocator: Allocator,
    config: *const SystemConfig,
    dopamine_prediction_error: DopaminePredictionError,
    stdp_homeostatic: STDPHomeostatic,
    operant_matkowski: OperantMatkowski,
    pavlovian_bursting: PavlovianBursting,
    mirror_neurons: MirrorNeuronSystem,
    latent_world_model: LatentWorldModel,
    schema_active_inference: SchemaActiveInference,
    metaplasticity: Metaplasticity,
    temporal_error_accumulator: TemporalErrorAccumulator,
    habituation_sensitization: HabituationSensitization,
    insight_learning: InsightLearning,
    global_plasticity_state: PlasticityState,
    prng: std.rand.DefaultPrng,

    pub fn init(base_allocator: Allocator, config: *const SystemConfig) !NeurobiologicalLearningSystem {
        var scratch_arena = ArenaAllocator.init(base_allocator);
        const scratch_allocator = scratch_arena.allocator();

        var prng = std.rand.DefaultPrng.init(@intCast(std.time.timestamp()));
        return NeurobiologicalLearningSystem{
            .persistent_allocator = base_allocator,
            .scratch_arena = scratch_arena,
            .scratch_allocator = scratch_allocator,
            .config = config,
            .dopamine_prediction_error = try DopaminePredictionError.init(base_allocator, config),
            .stdp_homeostatic = try STDPHomeostatic.init(base_allocator, config),
            .operant_matkowski = try OperantMatkowski.init(base_allocator, config),
            .pavlovian_bursting = try PavlovianBursting.init(base_allocator, config, &prng),
            .mirror_neurons = try MirrorNeuronSystem.init(base_allocator, config),
            .latent_world_model = try LatentWorldModel.init(base_allocator, config),
            .schema_active_inference = try SchemaActiveInference.init(base_allocator, config, &prng),
            .metaplasticity = try Metaplasticity.init(base_allocator, config),
            .temporal_error_accumulator = try TemporalErrorAccumulator.init(base_allocator, config),
            .habituation_sensitization = try HabituationSensitization.init(base_allocator, config),
            .insight_learning = try InsightLearning.init(base_allocator, config),
            .global_plasticity_state = PlasticityState.init(),
            .prng = prng,
        };
    }

    pub fn deinit(self: *NeurobiologicalLearningSystem) void {
        self.dopamine_prediction_error.deinit();
        self.stdp_homeostatic.deinit();
        self.operant_matkowski.deinit();
        self.pavlovian_bursting.deinit();
        self.mirror_neurons.deinit();
        self.latent_world_model.deinit();
        self.schema_active_inference.deinit();
        self.metaplasticity.deinit();
        self.temporal_error_accumulator.deinit();
        self.habituation_sensitization.deinit();
        self.insight_learning.deinit();
        self.scratch_arena.deinit();
    }

    pub fn integratedLearn(self: *NeurobiologicalLearningSystem, input: []const f32, target: []const f32, context: *const LearningContext) !LearningResult {
        _ = self.scratch_arena.reset(.retain_capacity);

        var result = LearningResult.init(self.persistent_allocator);

        const dpe_output = try self.dopamine_prediction_error.processSensoryReward(input, target, context.reward, self.scratch_allocator);
        defer self.persistent_allocator.free(dpe_output.synaptic_traces);

        result.dopamine_signal = dpe_output.dopamine_level;
        result.prediction_error = dpe_output.error_magnitude;

        const current_metaplastic_state = self.metaplasticity.getCurrentState();
        const homeostatic_factor = self.metaplasticity.computeHomeostaticFactor();

        try self.stdp_homeostatic.applyPlasticity(dpe_output.synaptic_traces, current_metaplastic_state, homeostatic_factor, self.scratch_allocator);

        if (self.stdp_homeostatic.requiresSleepPhase()) {
            try self.stdp_homeostatic.executeSleepBasedConsolidation(&self.prng, self.scratch_allocator);
            self.global_plasticity_state.sleep_cycle_count += 1;
        }

        const operant_probability = try self.operant_matkowski.computeResponseProbability(input, dpe_output.reward_history, self.scratch_allocator);
        result.action_probabilities = operant_probability.distributions;

        if (context.contains_social_observation) {
            const mirror_activation = try self.mirror_neurons.processObservationAction(input, context.observed_action, self.scratch_allocator);
            result.empathy_signal = mirror_activation.empathy_level;
            result.mirror_neuron_index = mirror_activation.cmni_idx;
        }

        const pavlovian_response = try self.pavlovian_bursting.processConditionedStimulus(input, dpe_output.dopamine_level);
        result.conditioned_response = pavlovian_response.burst_amplitude;
        result.network_morphology = pavlovian_response.feedforward_ratio;

        const latent_prediction = try self.latent_world_model.predictLatentAction(input, context.temporal_sequence, self.scratch_allocator);
        result.latent_world_state = latent_prediction.state_representation;

        const schema_inference = try self.schema_active_inference.inferSchema(input, latent_prediction.state_representation, self.scratch_allocator);
        result.schema_activation = schema_inference.active_schemas;
        result.free_energy = schema_inference.free_energy_minimization;

        try self.temporal_error_accumulator.accumulateError(dpe_output.error_magnitude, context.time_step, self.scratch_allocator);
        result.accumulated_error = self.temporal_error_accumulator.getAccumulatedValue();

        const habituation_state = try self.habituation_sensitization.processStimulus(input, context.stimulus_intensity, self.scratch_allocator);
        result.response_modulation = habituation_state.response_magnitude;
        result.habituation_level = habituation_state.habituation_degree;
        result.sensitization_level = habituation_state.sensitization_degree;

        if (self.insight_learning.detectAhaCondition(result.accumulated_error, schema_inference.schema_coherence)) {
            const insight_weights_slice = self.schema_active_inference.getModifiableWeights();
            const insight = try self.insight_learning.triggerInsight(schema_inference.active_schemas, insight_weights_slice, &self.prng, self.scratch_allocator);
            result.insight_occurred = true;
            result.insight_solution = insight.solution_representation;
            try self.schema_active_inference.integrateInsight(insight.solution_representation);
        }

        try self.metaplasticity.updatePlasticityThreshold(result.dopamine_signal, self.stdp_homeostatic.getOverallActivity());

        self.global_plasticity_state.total_learning_steps += 1;
        self.global_plasticity_state.cumulative_dopamine += result.dopamine_signal;

        return result;
    }

    pub fn consolidateMemory(self: *NeurobiologicalLearningSystem) !void {
        try self.pavlovian_bursting.stabilizeFeedforwardStructure();
        try self.latent_world_model.consolidateLatentRepresentations(self.scratch_allocator);
        try self.schema_active_inference.updateSchemaHierarchy();
        try self.insight_learning.pruneInsightCandidates();
    }
};

const DopaminePredictionError = struct {
    allocator: Allocator,
    sensory_prediction: []f32,
    reward_prediction: []f32,
    dopamine_neurons: []DopamineNeuron,
    reward_history: []f32,
    sensory_history: []f32,
    basal_dopamine: f32,
    phasic_dopamine: f32,
    config: *const SystemConfig,

    pub fn init(allocator: Allocator, config: *const SystemConfig) !DopaminePredictionError {
        const neuron_count = config.dopamine_neuron_count;
        const history_length = config.dopamine_history_len;

        var neurons = try allocator.alloc(DopamineNeuron, neuron_count);
        for (neurons) |*neuron| {
            neuron.* = DopamineNeuron.init(config);
        }

        var sensory_pred = try allocator.alloc(f32, history_length);
        var reward_pred = try allocator.alloc(f32, history_length);
        var reward_hist = try allocator.alloc(f32, history_length);
        var sensory_hist = try allocator.alloc(f32, history_length);

        @memset(sensory_pred, 0.0);
        @memset(reward_pred, 0.0);
        @memset(reward_hist, 0.0);
        @memset(sensory_hist, 0.0);

        return DopaminePredictionError{
            .allocator = allocator,
            .sensory_prediction = sensory_pred,
            .reward_prediction = reward_pred,
            .dopamine_neurons = neurons,
            .reward_history = reward_hist,
            .sensory_history = sensory_hist,
            .basal_dopamine = config.dopamine_basal_level,
            .phasic_dopamine = 0.0,
            .config = config,
        };
    }

    pub fn deinit(self: *DopaminePredictionError) void {
        self.allocator.free(self.sensory_prediction);
        self.allocator.free(self.reward_prediction);
        self.allocator.free(self.dopamine_neurons);
        self.allocator.free(self.reward_history);
        self.allocator.free(self.sensory_history);
    }

    pub fn processSensoryReward(self: *DopaminePredictionError, sensory_input: []const f32, target: []const f32, reward: f32, scratch: Allocator) !DopamineOutput {
        const sensory_error = try self.computeSensoryPredictionError(sensory_input, target, scratch);
        const reward_error = try self.computeRewardPredictionError(reward, scratch);

        const integrated_error = self.config.dopamine_weight_sensory * sensory_error + self.config.dopamine_weight_reward * reward_error;

        self.phasic_dopamine = self.basal_dopamine + integrated_error * self.config.dopamine_error_gain;
        self.phasic_dopamine = math.clamp(self.phasic_dopamine, 0.0, 1.0);

        self.updateNeuronsSimd(self.phasic_dopamine, integrated_error);

        try self.updatePredictions(sensory_input, reward);

        const synaptic_traces = try self.computeSynapticTraces(scratch);

        return DopamineOutput{
            .dopamine_level = self.phasic_dopamine,
            .error_magnitude = @abs(integrated_error),
            .sensory_component = sensory_error,
            .reward_component = reward_error,
            .synaptic_traces = synaptic_traces,
            .reward_history = self.reward_history,
        };
    }

    fn computeSensoryPredictionError(self: *DopaminePredictionError, sensory_input: []const f32, target: []const f32, scratch: Allocator) !f32 {
        _ = scratch;
        const dim = math.min(sensory_input.len, target.len);
        if (dim == 0) return 0.0;

        const vec_width = self.config.vector_width;
        const vec_len = dim - (dim % vec_width);

        var error_sum: f32 = 0.0;
        var i: usize = 0;

        const lr_vec = @as(@Vector(vec_width, f32), @splat(self.config.dopamine_sensory_lr));

        while (i < vec_len) : (i += vec_width) {
            const target_vec: @Vector(vec_width, f32) = target[i..][0..vec_width].*;

            var pred_vec: @Vector(vec_width, f32) = undefined;
            for (0..vec_width) |j| {
                const idx = (i + j) % self.sensory_prediction.len;
                pred_vec[j] = self.sensory_prediction[idx];
            }

            const error_vec = target_vec - pred_vec;
            error_sum += @reduce(.Add, error_vec * error_vec);

            const updated_pred = pred_vec + lr_vec * error_vec;

            for (0..vec_width) |j| {
                const idx = (i + j) % self.sensory_prediction.len;
                self.sensory_prediction[idx] = updated_pred[j];
            }
        }

        while (i < dim) : (i += 1) {
            const prediction_idx = i % self.sensory_prediction.len;
            const prediction = self.sensory_prediction[prediction_idx];
            const error = target[i] - prediction;
            error_sum += error * error;
            self.sensory_prediction[prediction_idx] = prediction + self.config.dopamine_sensory_lr * error;
        }

        return @sqrt(error_sum / @as(f32, @floatFromInt(dim)));
    }

    fn computeRewardPredictionError(self: *DopaminePredictionError, reward: f32, scratch: Allocator) !f32 {
        _ = scratch;
        const predicted_reward = self.reward_prediction[0];
        const error = reward - predicted_reward;

        std.mem.copyBackwards(f32, self.reward_prediction[1..], self.reward_prediction[0 .. self.reward_prediction.len - 1]);
        self.reward_prediction[0] = predicted_reward + self.config.dopamine_reward_lr * error;

        return error;
    }

    fn updatePredictions(self: *DopaminePredictionError, sensory_input: []const f32, reward: f32) !void {
        std.mem.copyBackwards(f32, self.reward_history[1..], self.reward_history[0 .. self.reward_history.len - 1]);
        self.reward_history[0] = reward;

        const input_hash = hashInputSimd(sensory_input, self.config.vector_width);
        std.mem.copyBackwards(f32, self.sensory_history[1..], self.sensory_history[0 .. self.sensory_history.len - 1]);
        self.sensory_history[0] = input_hash;
    }

    fn computeSynapticTraces(self: *DopaminePredictionError, scratch: Allocator) ![]f32 {
        const traces = try scratch.alloc(f32, self.dopamine_neurons.len);
        for (self.dopamine_neurons, 0..) |neuron, i| {
            traces[i] = neuron.synaptic_trace;
        }
        return traces;
    }

    fn updateNeuronsSimd(self: *DopaminePredictionError, dopamine_level: f32, error: f32) void {
        const vec_width = self.config.vector_width;
        const count = self.dopamine_neurons.len;
        const vec_count = count - (count % vec_width);

        const burst_thresh = @as(@Vector(vec_width, f32), @splat(self.config.dopamine_burst_threshold));
        const base = @as(@Vector(vec_width, f32), @splat(self.config.dopamine_basal_rate));
        const high_mult = @as(@Vector(vec_width, f32), @splat(1.0 + self.config.dopamine_burst_multiplier * dopamine_level));
        const low_mult = @as(@Vector(vec_width, f32), @splat(self.config.dopamine_depression_rate));
        const decay = @as(@Vector(vec_width, f32), @splat(self.config.dopamine_trace_decay));
        const trace_contrib = @as(@Vector(vec_width, f32), @splat(self.config.dopamine_trace_contrib));

        var i: usize = 0;
        while (i < vec_count) : (i += vec_width) {
            var rate_vec: @Vector(vec_width, f32) = undefined;
            var trace_vec: @Vector(vec_width, f32) = undefined;

            for (0..vec_width) |j| {
                rate_vec[j] = self.dopamine_neurons[i + j].firing_rate;
                trace_vec[j] = self.dopamine_neurons[i + j].synaptic_trace;
            }

            const error_vec = @as(@Vector(vec_width, f32), @splat(error));
            const high_mask = error_vec > burst_thresh;
            const low_mask = error_vec < -burst_thresh;

            const target_rate = @select(f32, high_mask, base * high_mult, @select(f32, low_mask, base * low_mult, base));
            rate_vec = target_rate;
            trace_vec = trace_vec * decay + rate_vec * trace_contrib;

            for (0..vec_width) |j| {
                self.dopamine_neurons[i + j].firing_rate = rate_vec[j];
                self.dopamine_neurons[i + j].synaptic_trace = trace_vec[j];
            }
        }

        while (i < count) : (i += 1) {
            const neuron = &self.dopamine_neurons[i];
            if (error > self.config.dopamine_burst_threshold) {
                neuron.firing_rate = self.config.dopamine_basal_rate * (1.0 + self.config.dopamine_burst_multiplier * dopamine_level);
            } else if (error < -self.config.dopamine_burst_threshold) {
                neuron.firing_rate = self.config.dopamine_basal_rate * self.config.dopamine_depression_rate;
            } else {
                neuron.firing_rate = self.config.dopamine_basal_rate;
            }
            neuron.synaptic_trace = neuron.synaptic_trace * self.config.dopamine_trace_decay + neuron.firing_rate * self.config.dopamine_trace_contrib;
        }
    }
};

const DopamineNeuron = struct {
    firing_rate: f32,
    synaptic_trace: f32,

    pub fn init(config: *const SystemConfig) DopamineNeuron {
        return DopamineNeuron{
            .firing_rate = config.dopamine_basal_rate,
            .synaptic_trace = 0.0,
        };
    }
};

const STDPHomeostatic = struct {
    allocator: Allocator,
    weights: []f32,
    pre_traces: []f32,
    post_traces: []f32,
    learning_rate: f32,
    tau_pre: f32,
    tau_post: f32,
    sleep_threshold: f32,
    activity_counter: f32,
    target_firing_rate: f32,
    current_firing_rate: f32,
    weight_decay_rate: f32,
    homeostatic_scale: f32,
    sleep_consolidation_strength: f32,
    num_neurons: usize,
    config: *const SystemConfig,

    pub fn init(allocator: Allocator, config: *const SystemConfig) !STDPHomeostatic {
        const num_neurons = config.stdp_neuron_count;
        const num_synapses = num_neurons * num_neurons;

        var weights = try allocator.alloc(f32, num_synapses);
        var pre_traces = try allocator.alloc(f32, num_neurons);
        var post_traces = try allocator.alloc(f32, num_neurons);

        var prng = std.rand.DefaultPrng.init(12345);
        const random = prng.random();

        const vec_width = config.vector_width;
        const vec_count = num_synapses - (num_synapses % vec_width);
        const init_scale = @as(@Vector(vec_width, f32), @splat(0.1));

        var i: usize = 0;
        while (i < vec_count) : (i += vec_width) {
            var v: @Vector(vec_width, f32) = undefined;
            for (0..vec_width) |j| {
                v[j] = random.float(f32);
            }
            @memcpy(weights[i..][0..vec_width], &(v * init_scale));
        }
        while (i < num_synapses) : (i += 1) {
            weights[i] = random.float(f32) * 0.1;
        }

        @memset(pre_traces, 0.0);
        @memset(post_traces, 0.0);

        return STDPHomeostatic{
            .allocator = allocator,
            .weights = weights,
            .pre_traces = pre_traces,
            .post_traces = post_traces,
            .learning_rate = config.stdp_learning_rate,
            .tau_pre = config.stdp_tau_pre,
            .tau_post = config.stdp_tau_post,
            .sleep_threshold = config.stdp_sleep_threshold,
            .activity_counter = 0.0,
            .target_firing_rate = config.stdp_target_firing,
            .current_firing_rate = 0.0,
            .weight_decay_rate = config.stdp_weight_decay,
            .homeostatic_scale = 1.0,
            .sleep_consolidation_strength = config.stdp_consolidation_strength,
            .num_neurons = num_neurons,
            .config = config,
        };
    }

    pub fn deinit(self: *STDPHomeostatic) void {
        self.allocator.free(self.weights);
        self.allocator.free(self.pre_traces);
        self.allocator.free(self.post_traces);
    }

    pub fn applyPlasticity(self: *STDPHomeostatic, synaptic_traces: []const f32, metaplastic_state: f32, homeostatic_factor: f32, scratch: Allocator) !void {
        _ = scratch;
        self.homeostatic_scale = homeostatic_factor;
        const effective_learning_rate = self.learning_rate * metaplastic_state * homeostatic_factor;

        var firing_sum: f32 = 0.0;
        const limit = math.min(synaptic_traces.len, self.num_neurons);

        const vec_width = self.config.vector_width;
        const spike_thresh = @as(@Vector(vec_width, f32), @splat(self.config.stdp_spike_threshold));
        const eff_lr_vec = @as(@Vector(vec_width, f32), @splat(effective_learning_rate));
        const w_min = @as(@Vector(vec_width, f32), @splat(self.config.stdp_min_weight));
        const w_max = @as(@Vector(vec_width, f32), @splat(self.config.stdp_max_weight));

        for (0..limit) |i| {
            if (synaptic_traces[i] > self.config.stdp_spike_threshold) firing_sum += 1.0;
        }
        self.current_firing_rate = firing_sum / @as(f32, @floatFromInt(self.num_neurons));

        for (0..self.num_neurons) |post_idx| {
            const trace_val = if (post_idx < synaptic_traces.len) synaptic_traces[post_idx] else 0.0;
            const post_spike = trace_val > self.config.stdp_spike_threshold;

            if (post_spike) {
                const row_offset = post_idx * self.num_neurons;
                const pre_vec_count = self.num_neurons - (self.num_neurons % vec_width);
                var k: usize = 0;

                while (k < pre_vec_count) : (k += vec_width) {
                    const pre_traces_vec: @Vector(vec_width, f32) = self.pre_traces[k..][0..vec_width].*;

                    var weights_vec = self.weights[row_offset + k..][0..vec_width].*;
                    const delta_w = eff_lr_vec * pre_traces_vec;
                    weights_vec = weights_vec + delta_w;
                    weights_vec = @max(w_min, @min(w_max, weights_vec));
                    @memcpy(self.weights[row_offset + k..][0..vec_width], &weights_vec);
                }

                while (k < self.num_neurons) : (k += 1) {
                    const synapse_idx = row_offset + k;
                    const delta_w = effective_learning_rate * self.pre_traces[k];
                    self.weights[synapse_idx] += delta_w;
                    self.weights[synapse_idx] = math.clamp(self.weights[synapse_idx], self.config.stdp_min_weight, self.config.stdp_max_weight);
                }

                self.post_traces[post_idx] = 1.0;
            }
        }

        for (0..self.num_neurons) |pre_idx| {
            const trace_val = if (pre_idx < synaptic_traces.len) synaptic_traces[pre_idx] else 0.0;
            const pre_spike = trace_val > self.config.stdp_spike_threshold;

            if (pre_spike) {
                const post_vec_count = self.num_neurons - (self.num_neurons % vec_width);
                var k: usize = 0;

                while (k < post_vec_count) : (k += vec_width) {
                    const post_traces_vec: @Vector(vec_width, f32) = self.post_traces[k..][0..vec_width].*;

                    var weights_vec: @Vector(vec_width, f32) = undefined;
                    for (0..vec_width) |j| {
                        weights_vec[j] = self.weights[(k + j) * self.num_neurons + pre_idx];
                    }

                    const delta_w = -eff_lr_vec * post_traces_vec;
                    weights_vec = weights_vec + delta_w;
                    weights_vec = @max(w_min, @min(w_max, weights_vec));

                    for (0..vec_width) |j| {
                        self.weights[(k + j) * self.num_neurons + pre_idx] = weights_vec[j];
                    }
                }

                while (k < self.num_neurons) : (k += 1) {
                    const synapse_idx = k * self.num_neurons + pre_idx;
                    const delta_w = -effective_learning_rate * self.post_traces[k];
                    self.weights[synapse_idx] += delta_w;
                    self.weights[synapse_idx] = math.clamp(self.weights[synapse_idx], self.config.stdp_min_weight, self.config.stdp_max_weight);
                }

                self.pre_traces[pre_idx] = 1.0;
            }
        }

        const decay_pre = @as(@Vector(vec_width, f32), @splat(@exp(-1.0 / self.tau_pre)));
        const decay_post = @as(@Vector(vec_width, f32), @splat(@exp(-1.0 / self.tau_post)));

        const trace_vec_count = self.num_neurons - (self.num_neurons % vec_width);
        var t: usize = 0;
        while (t < trace_vec_count) : (t += vec_width) {
            var p_vec = self.pre_traces[t..][0..vec_width].*;
            var po_vec = self.post_traces[t..][0..vec_width].*;
            p_vec = p_vec * decay_pre;
            po_vec = po_vec * decay_post;
            @memcpy(self.pre_traces[t..][0..vec_width], &p_vec);
            @memcpy(self.post_traces[t..][0..vec_width], &po_vec);
        }
        while (t < self.num_neurons) : (t += 1) {
            self.pre_traces[t] *= @exp(-1.0 / self.tau_pre);
            self.post_traces[t] *= @exp(-1.0 / self.tau_post);
        }

        self.activity_counter += 1.0;
    }

    pub fn requiresSleepPhase(self: *STDPHomeostatic) bool {
        return self.activity_counter >= self.sleep_threshold;
    }

    pub fn executeSleepBasedConsolidation(self: *STDPHomeostatic, prng: *std.rand.DefaultPrng, scratch: Allocator) !void {
        _ = scratch;
        const random = prng.random();
        const noise_scale = self.config.stdp_sleep_noise;

        const vec_width = self.config.vector_width;
        const w_count = self.weights.len;
        const vec_count = w_count - (w_count % vec_width);

        const noise_scale_vec = @as(@Vector(vec_width, f32), @splat(noise_scale * 2.0));
        const half = @as(@Vector(vec_width, f32), @splat(0.5));
        const prune_thresh = @as(@Vector(vec_width, f32), @splat(self.config.stdp_prune_thresh));
        const growth_thresh = @as(@Vector(vec_width, f32), @splat(0.8));
        const growth_factor = @as(@Vector(vec_width, f32), @splat(self.config.stdp_growth_factor));
        const max_w = @as(@Vector(vec_width, f32), @splat(self.config.stdp_max_weight));
        const decay_factor = @as(@Vector(vec_width, f32), @splat(1.0 - self.weight_decay_rate));
        const min_w = @as(@Vector(vec_width, f32), @splat(self.config.stdp_min_weight));
        const prune_factor = @as(@Vector(vec_width, f32), @splat(0.8));

        var i: usize = 0;
        while (i < vec_count) : (i += vec_width) {
            var w_vec = self.weights[i..][0..vec_width].*;

            var noise_vec: @Vector(vec_width, f32) = undefined;
            for (0..vec_width) |j| {
                noise_vec[j] = random.float(f32);
            }
            w_vec = w_vec + (noise_vec - half) * noise_scale_vec;

            const mask_prune = w_vec < prune_thresh;
            w_vec = @select(f32, mask_prune, w_vec * prune_factor, w_vec);

            const mask_grow = w_vec > growth_thresh;
            w_vec = @select(f32, mask_grow, @min(max_w, w_vec * growth_factor), w_vec);

            w_vec = w_vec * decay_factor;
            w_vec = @max(min_w, @min(max_w, w_vec));

            @memcpy(self.weights[i..][0..vec_width], &w_vec);
        }
        while (i < w_count) : (i += 1) {
            const noise = (random.float(f32) - 0.5) * noise_scale * 2.0;
            self.weights[i] += noise;

            if (self.weights[i] < self.config.stdp_prune_thresh) {
                self.weights[i] *= 0.8;
            } else if (self.weights[i] > 0.8) {
                self.weights[i] = math.min(self.config.stdp_max_weight, self.weights[i] * self.config.stdp_growth_factor);
            }

            self.weights[i] *= (1.0 - self.weight_decay_rate);
            self.weights[i] = math.clamp(self.weights[i], self.config.stdp_min_weight, self.config.stdp_max_weight);
        }

        const firing_rate_error = self.current_firing_rate - self.target_firing_rate;
        const scale_factor = 1.0 - self.sleep_consolidation_strength * firing_rate_error / self.target_firing_rate;

        const scale_vec = @as(@Vector(vec_width, f32), @splat(scale_factor));
        var k: usize = 0;
        while (k < vec_count) : (k += vec_width) {
            var w_vec = self.weights[k..][0..vec_width].*;
            w_vec = w_vec * scale_vec;
            w_vec = @max(min_w, @min(max_w, w_vec));
            @memcpy(self.weights[k..][0..vec_width], &w_vec);
        }
        while (k < w_count) : (k += 1) {
            self.weights[k] *= scale_factor;
            self.weights[k] = math.clamp(self.weights[k], self.config.stdp_min_weight, self.config.stdp_max_weight);
        }

        self.activity_counter = 0.0;
    }

    pub fn getOverallActivity(self: *STDPHomeostatic) f32 {
        return self.current_firing_rate;
    }
};

const OperantMatkowski = struct {
    allocator: Allocator,
    response_probabilities: []f32,
    reinforcement_history: []f32,
    contraction_constant: f32,
    integral_kernel: []f32,
    picard_iterations: usize,
    convergence_threshold: f32,
    config: *const SystemConfig,

    pub fn init(allocator: Allocator, config: *const SystemConfig) !OperantMatkowski {
        const response_dim = config.operant_dim;
        const history_len = config.operant_history;
        const kernel_size = config.operant_kernel;

        var response_probs = try allocator.alloc(f32, response_dim);
        var reinf_history = try allocator.alloc(f32, history_len);
        var kernel = try allocator.alloc(f32, kernel_size);

        const init_val = 1.0 / @as(f32, @floatFromInt(response_dim));
        @memset(response_probs, init_val);
        @memset(reinf_history, 0.0);

        for (kernel, 0..) |*k, i| {
            const t = @as(f32, @floatFromInt(i)) / @as(f32, @floatFromInt(kernel_size));
            k.* = @exp(-t * 2.0);
        }

        return OperantMatkowski{
            .allocator = allocator,
            .response_probabilities = response_probs,
            .reinforcement_history = reinf_history,
            .contraction_constant = config.operant_contraction,
            .integral_kernel = kernel,
            .picard_iterations = config.operant_iterations,
            .convergence_threshold = config.operant_convergence,
            .config = config,
        };
    }

    pub fn deinit(self: *OperantMatkowski) void {
        self.allocator.free(self.response_probabilities);
        self.allocator.free(self.reinforcement_history);
        self.allocator.free(self.integral_kernel);
    }

    pub fn computeResponseProbability(self: *OperantMatkowski, stimulus: []const f32, reward_history: []const f32, scratch: Allocator) !OperantOutput {
        const copy_len = @min(reward_history.len, self.reinforcement_history.len);
        @memcpy(self.reinforcement_history[0..copy_len], reward_history[0..copy_len]);

        var current_iterate = try scratch.alloc(f32, self.response_probabilities.len);
        @memcpy(current_iterate, self.response_probabilities);

        var next_iterate = try scratch.alloc(f32, self.response_probabilities.len);

        var iteration: usize = 0;
        const contraction_vec = @as(@Vector(self.config.vector_width, f32), @splat(self.contraction_constant));
        const stim_weight_vec = @as(@Vector(self.config.vector_width, f32), @splat(self.config.operant_stimulus_weight));

        while (iteration < self.picard_iterations) : (iteration += 1) {
            var max_diff: f32 = 0.0;

            const vec_width = self.config.vector_width;
            const dim = self.response_probabilities.len;
            const vec_limit = dim - (dim % vec_width);

            var i: usize = 0;
            while (i < vec_limit) : (i += vec_width) {
                var integral_vec: @Vector(vec_width, f32) = @splat(0.0);
                var stim_vec: @Vector(vec_width, f32) = undefined;

                for (0..vec_width) |j| {
                    stim_vec[j] = if (i + j < stimulus.len) stimulus[i + j] else 0.0;
                }

                for (0..@min(self.integral_kernel.len, dim)) |j| {
                    const kernel_weight = self.integral_kernel[j];
                    const reinforcement_weight = if (j < self.reinforcement_history.len) self.reinforcement_history[j] else 0.0;

                    var offset_vec: @Vector(vec_width, f32) = undefined;
                    for (0..vec_width) |k| {
                        const idx = (i + k + j) % dim;
                        offset_vec[k] = current_iterate[idx];
                    }

                    integral_vec += @as(@Vector(vec_width, f32), @splat(kernel_weight * (1.0 + reinforcement_weight))) * offset_vec;
                }

                const new_val = contraction_vec * integral_vec + stim_weight_vec * stim_vec;

                const old_val_vec: @Vector(vec_width, f32) = current_iterate[i..][0..vec_width].*;
                const diff_vec = @abs(new_val - old_val_vec);
                const local_max = @reduce(.Max, diff_vec);
                if (local_max > max_diff) max_diff = local_max;

                @memcpy(next_iterate[i..][0..vec_width], &new_val);
            }

            while (i < dim) : (i += 1) {
                var integral_sum: f32 = 0.0;
                for (0..@min(self.integral_kernel.len, dim)) |j| {
                    const idx = (i + j) % dim;
                    const kernel_weight = self.integral_kernel[j];
                    const reinforcement_weight = if (j < self.reinforcement_history.len) self.reinforcement_history[j] else 0.0;
                    integral_sum += kernel_weight * current_iterate[idx] * (1.0 + reinforcement_weight);
                }
                const stimulus_influence = if (i < stimulus.len) stimulus[i] else 0.0;
                const new_val = self.contraction_constant * integral_sum + self.config.operant_stimulus_weight * stimulus_influence;

                const diff = @abs(new_val - current_iterate[i]);
                if (diff > max_diff) max_diff = diff;

                next_iterate[i] = new_val;
            }

            @memcpy(current_iterate, next_iterate);
            if (max_diff < self.convergence_threshold) break;
        }

        @memcpy(self.response_probabilities, current_iterate);

        var sum: f32 = 0.0;
        for (self.response_probabilities) |p| sum += p;

        if (sum > self.config.operant_epsilon) {
            for (self.response_probabilities) |*p| {
                p.* /= sum;
            }
        } else {
            const uniform = 1.0 / @as(f32, @floatFromInt(self.response_probabilities.len));
            @memset(self.response_probabilities, uniform);
        }

        const distributions = try self.allocator.alloc(f32, self.response_probabilities.len);
        @memcpy(distributions, self.response_probabilities);

        return OperantOutput{
            .distributions = distributions,
            .convergence_iterations = iteration,
            .fixed_point_reached = iteration < self.picard_iterations,
        };
    }
};

const PavlovianBursting = struct {
    allocator: Allocator,
    network_weights: []f32,
    burst_profiles: []BurstProfile,
    feedforward_ratio: f32,
    recurrent_ratio: f32,
    dopamine_modulation: f32,
    basal_dopamine: f32,
    conditioning_trials: usize,
    population_size: usize,
    target_population_idx: usize,
    restructure_rate: f32,
    dopamine_threshold: f32,
    config: *const SystemConfig,

    pub fn init(allocator: Allocator, config: *const SystemConfig, prng: *std.rand.DefaultPrng) !PavlovianBursting {
        const pop_size = config.pavlovian_pop;
        const num_connections = pop_size * pop_size;

        var weights = try allocator.alloc(f32, num_connections);
        var bursts = try allocator.alloc(BurstProfile, pop_size);

        const random = prng.random();
        const vec_width = config.vector_width;
        const init_min = @as(@Vector(vec_width, f32), @splat(-0.1));
        const init_max = @as(@Vector(vec_width, f32), @splat(0.1));

        const w_count = num_connections - (num_connections % vec_width);
        var i: usize = 0;
        while (i < w_count) : (i += vec_width) {
            var r_vec: @Vector(vec_width, f32) = undefined;
            for (0..vec_width) |j| {
                r_vec[j] = random.float(f32);
            }
            const w_vec = init_min + (init_max - init_min) * r_vec;
            @memcpy(weights[i..][0..vec_width], &w_vec);
        }
        while (i < num_connections) : (i += 1) {
            weights[i] = (random.float(f32) - 0.5) * 0.2;
        }

        for (bursts) |*b| {
            b.* = BurstProfile.init(config);
        }

        return PavlovianBursting{
            .allocator = allocator,
            .network_weights = weights,
            .burst_profiles = bursts,
            .feedforward_ratio = config.pavlovian_feed_init,
            .recurrent_ratio = config.pavlovian_recur_init,
            .dopamine_modulation = config.pavlovian_feed_init,
            .basal_dopamine = config.pavlovian_feed_init,
            .conditioning_trials = 0,
            .population_size = pop_size,
            .target_population_idx = config.pavlovian_target_idx % pop_size,
            .restructure_rate = config.pavlovian_restructure,
            .dopamine_threshold = config.pavlovian_dopa_thresh,
            .config = config,
        };
    }

    pub fn deinit(self: *PavlovianBursting) void {
        self.allocator.free(self.network_weights);
        self.allocator.free(self.burst_profiles);
    }

    pub fn processConditionedStimulus(self: *PavlovianBursting, stimulus: []const f32, dopamine_level: f32) !PavlovianOutput {
        self.dopamine_modulation = self.basal_dopamine + dopamine_level;

        for (self.burst_profiles, 0..) |*burst, idx| {
            burst.reset();

            const is_target = (idx == self.target_population_idx);
            const stimulus_strength = if (idx < stimulus.len) stimulus[idx] else 0.0;

            if (is_target and self.dopamine_modulation > 0.3) {
                burst.amplitude = self.config.pavlovian_burst_gain + self.dopamine_modulation * 3.0;
                burst.symmetry = self.config.pavlovian_sym_gain;
            } else {
                burst.amplitude = 0.5 + stimulus_strength * 0.5;
                burst.symmetry = 0.4 + stimulus_strength * 0.2;
            }

            burst.peak_time = self.config.pavlovian_peak_base + @as(f32, @floatFromInt(idx % 20)) * self.config.pavlovian_peak_spread;
        }

        if (self.dopamine_modulation > self.dopamine_threshold) {
            try self.restructureNetwork();
            self.conditioning_trials += 1;
        }

        const target_burst = self.burst_profiles[self.target_population_idx];

        return PavlovianOutput{
            .burst_amplitude = target_burst.amplitude,
            .burst_symmetry = target_burst.symmetry,
            .feedforward_ratio = self.feedforward_ratio,
            .conditioning_progress = @as(f32, @floatFromInt(self.conditioning_trials)) / 500.0,
        };
    }

    fn restructureNetwork(self: *PavlovianBursting) !void {
        const vec_width = self.config.vector_width;
        const restructure_vec = @as(@Vector(vec_width, f32), @splat(self.restructure_rate * self.dopamine_modulation));
        const decay_vec = @as(@Vector(vec_width, f32), @splat(1.0 - self.restructure_rate * 0.5));
        const one = @as(@Vector(vec_width, f32), @splat(1.0));
        const max_w = @as(@Vector(vec_width, f32), @splat(1.0));

        for (0..self.population_size) |post_idx| {
            const row_offset = post_idx * self.population_size;
            const vec_count = self.population_size - (self.population_size % vec_width);

            var i: usize = 0;
            while (i < vec_count) : (i += vec_width) {
                var w_vec = self.network_weights[row_offset + i..][0..vec_width].*;
                var is_feedforward_vec: @Vector(vec_width, bool) = undefined;

                for (0..vec_width) |j| {
                    const pre_idx = i + j;
                    const is_feedforward_path = (pre_idx < post_idx) and (post_idx == self.target_population_idx or pre_idx < self.target_population_idx);
                    is_feedforward_vec[j] = is_feedforward_path;
                }

                w_vec = @select(f32, is_feedforward_vec, @min(max_w, w_vec + restructure_vec), w_vec * decay_vec);
                @memcpy(self.network_weights[row_offset + i..][0..vec_width], &w_vec);
            }

            while (i < self.population_size) : (i += 1) {
                const weight_idx = row_offset + i;
                const pre_idx = i;

                const is_feedforward_path = (pre_idx < post_idx) and (post_idx == self.target_population_idx or pre_idx < self.target_population_idx);

                if (is_feedforward_path) {
                    self.network_weights[weight_idx] += self.restructure_rate * self.dopamine_modulation;
                    self.network_weights[weight_idx] = @min(1.0, self.network_weights[weight_idx]);
                } else {
                    self.network_weights[weight_idx] *= (1.0 - self.restructure_rate * 0.5);
                }
            }
        }

        self.feedforward_ratio += self.restructure_rate * 0.1;
        self.feedforward_ratio = @min(0.95, self.feedforward_ratio);
        self.recurrent_ratio = 1.0 - self.feedforward_ratio;
    }

    pub fn stabilizeFeedforwardStructure(self: *PavlovianBursting) !void {
        const stability_threshold = self.config.pavlovian_stability_thresh;

        const vec_width = self.config.vector_width;
        const thresh_vec = @as(@Vector(vec_width, f32), @splat(stability_threshold));
        const prune_factor = @as(@Vector(vec_width, f32), @splat(0.5));
        const growth_thresh = @as(@Vector(vec_width, f32), @splat(0.7));
        const growth_factor = @as(@Vector(vec_width, f32), @splat(1.02));
        const max_w = @as(@Vector(vec_width, f32), @splat(1.0));

        const w_count = self.network_weights.len;
        const vec_count = w_count - (w_count % vec_width);

        var i: usize = 0;
        while (i < vec_count) : (i += vec_width) {
            var w_vec = self.network_weights[i..][0..vec_width].*;
            const abs_w = @abs(w_vec);
            const prune_mask = abs_w < thresh_vec;
            const grow_mask = w_vec > growth_thresh;

            w_vec = @select(f32, prune_mask, w_vec * prune_factor, w_vec);
            w_vec = @select(f32, grow_mask, @min(max_w, w_vec * growth_factor), w_vec);

            @memcpy(self.network_weights[i..][0..vec_width], &w_vec);
        }

        while (i < w_count) : (i += 1) {
            if (@abs(self.network_weights[i]) < stability_threshold) {
                self.network_weights[i] *= 0.5;
            } else if (self.network_weights[i] > 0.7) {
                self.network_weights[i] = @min(1.0, self.network_weights[i] * 1.02);
            }
        }
    }
};

const BurstProfile = struct {
    amplitude: f32,
    peak_time: f32,
    symmetry: f32,
    duration: f32,

    pub fn init(config: *const SystemConfig) BurstProfile {
        _ = config;
        return BurstProfile{
            .amplitude = 0.5,
            .peak_time = 50.0,
            .symmetry = 0.5,
            .duration = 100.0,
        };
    }

    pub fn reset(self: *BurstProfile) void {
        self.amplitude = 0.5;
        self.symmetry = 0.5;
    }
};

const MirrorNeuronSystem = struct {
    allocator: Allocator,
    mirror_neurons: []MirrorNeuron,
    self_action_patterns: []f32,
    observed_action_patterns: []f32,
    shared_representations: []f32,
    empathy_level: f32,
    cmni_score: f32,
    perception_action_coupling: f32,
    config: *const SystemConfig,

    pub fn init(allocator: Allocator, config: *const SystemConfig) !MirrorNeuronSystem {
        const neuron_count = config.mirror_count;
        const pattern_dim = config.mirror_pattern_dim;

        var neurons = try allocator.alloc(MirrorNeuron, neuron_count);
        for (neurons) |*n| {
            n.* = MirrorNeuron.init(config);
        }

        var self_patterns = try allocator.alloc(f32, pattern_dim);
        var obs_patterns = try allocator.alloc(f32, pattern_dim);
        var shared_reps = try allocator.alloc(f32, pattern_dim);

        @memset(self_patterns, 0.0);
        @memset(obs_patterns, 0.0);
        @memset(shared_reps, 0.0);

        return MirrorNeuronSystem{
            .allocator = allocator,
            .mirror_neurons = neurons,
            .self_action_patterns = self_patterns,
            .observed_action_patterns = obs_patterns,
            .shared_representations = shared_reps,
            .empathy_level = 0.0,
            .cmni_score = 0.0,
            .perception_action_coupling = config.mirror_coupling,
            .config = config,
        };
    }

    pub fn deinit(self: *MirrorNeuronSystem) void {
        self.allocator.free(self.mirror_neurons);
        self.allocator.free(self.self_action_patterns);
        self.allocator.free(self.observed_action_patterns);
        self.allocator.free(self.shared_representations);
    }

    pub fn processObservationAction(self: *MirrorNeuronSystem, observation: []const f32, action: []const f32, scratch: Allocator) !MirrorOutput {
        _ = scratch;

        const copy_obs = @min(observation.len, self.observed_action_patterns.len);
        @memcpy(self.observed_action_patterns[0..copy_obs], observation[0..copy_obs]);

        const copy_act = @min(action.len, self.self_action_patterns.len);
        @memcpy(self.self_action_patterns[0..copy_act], action[0..copy_act]);

        const vec_width = self.config.vector_width;
        const coupling_vec = @as(@Vector(vec_width, f32), @splat(self.perception_action_coupling));
        const one_minus_coupling = @as(@Vector(vec_width, f32), @splat(1.0 - self.perception_action_coupling));

        for (self.mirror_neurons, 0..) |*neuron, idx| {
            const obs_input = if (idx < observation.len) observation[idx] else 0.0;
            const act_input = if (idx < action.len) action[idx] else 0.0;

            neuron.updateActivation(obs_input, act_input, self.perception_action_coupling);
        }

        const shared_len = self.shared_representations.len;
        const vec_count = shared_len - (shared_len % vec_width);

        var i: usize = 0;
        while (i < vec_count) : (i += vec_width) {
            const self_vec: @Vector(vec_width, f32) = self.self_action_patterns[i..][0..vec_width].*;
            const obs_vec: @Vector(vec_width, f32) = self.observed_action_patterns[i..][0..vec_width].*;
            const shared_vec = (self_vec + obs_vec) * @as(@Vector(vec_width, f32), @splat(0.5));
            @memcpy(self.shared_representations[i..][0..vec_width], &shared_vec);
        }

        while (i < shared_len) : (i += 1) {
            self.shared_representations[i] = (self.self_action_patterns[i] + self.observed_action_patterns[i]) * 0.5;
        }

        self.cmni_score = try self.computeCMNI();
        self.empathy_level = self.computeEmpathy();

        return MirrorOutput{
            .empathy_level = self.empathy_level,
            .cmni_idx = self.cmni_score,
            .shared_activation = self.shared_representations[0],
        };
    }

    fn computeCMNI(self: *MirrorNeuronSystem) !f32 {
        var overlap_sum: f32 = 0.0;
        var self_norm: f32 = 0.0;
        var obs_norm: f32 = 0.0;

        const vec_width = self.config.vector_width;
        const len = self.self_action_patterns.len;
        const vec_count = len - (len % vec_width);

        var overlap_vec: @Vector(vec_width, f32) = @splat(0.0);
        var self_vec_acc: @Vector(vec_width, f32) = @splat(0.0);
        var obs_vec_acc: @Vector(vec_width, f32) = @splat(0.0);

        var i: usize = 0;
        while (i < vec_count) : (i += vec_width) {
            const s: @Vector(vec_width, f32) = self.self_action_patterns[i..][0..vec_width].*;
            const o: @Vector(vec_width, f32) = self.observed_action_patterns[i..][0..vec_width].*;
            overlap_vec += s * o;
            self_vec_acc += s * s;
            obs_vec_acc += o * o;
        }

        overlap_sum = @reduce(.Add, overlap_vec);
        self_norm = @reduce(.Add, self_vec_acc);
        obs_norm = @reduce(.Add, obs_vec_acc);

        while (i < len) : (i += 1) {
            const s = self.self_action_patterns[i];
            const o = self.observed_action_patterns[i];
            overlap_sum += s * o;
            self_norm += s * s;
            obs_norm += o * o;
        }

        const denominator = @sqrt(self_norm * obs_norm);
        if (denominator > self.config.mirror_epsilon) {
            return overlap_sum / denominator;
        }
        return 0.0;
    }

    fn computeEmpathy(self: *MirrorNeuronSystem) f32 {
        var activation_sum: f32 = 0.0;
        for (self.mirror_neurons) |neuron| {
            activation_sum += neuron.mirror_activation;
        }
        return activation_sum / @as(f32, @floatFromInt(self.mirror_neurons.len));
    }
};

const MirrorNeuron = struct {
    self_activation: f32,
    observed_activation: f32,
    mirror_activation: f32,
    coupling_strength: f32,

    pub fn init(config: *const SystemConfig) MirrorNeuron {
        return MirrorNeuron{
            .self_activation = 0.0,
            .observed_activation = 0.0,
            .mirror_activation = 0.0,
            .coupling_strength = config.mirror_base_coupling,
        };
    }

    pub fn updateActivation(self: *MirrorNeuron, obs_input: f32, self_input: f32, coupling: f32) void {
        self.self_activation = sigmoid(self_input);
        self.observed_activation = sigmoid(obs_input);

        self.mirror_activation = coupling * @min(self.self_activation, self.observed_activation) + (1.0 - coupling) * @max(self.self_activation, self.observed_activation);
    }
};

const LatentWorldModel = struct {
    allocator: Allocator,
    latent_states: []f32,
    action_representations: []f32,
    transition_model: []f32,
    state_dim: usize,
    action_dim: usize,
    temporal_depth: usize,
    config: *const SystemConfig,

    pub fn init(allocator: Allocator, config: *const SystemConfig) !LatentWorldModel {
        const state_dim = config.latent_state_dim;
        const action_dim = config.latent_action_dim;
        const depth = config.latent_depth;

        var latent_states = try allocator.alloc(f32, state_dim * depth);
        var action_reps = try allocator.alloc(f32, action_dim * depth);
        var trans_model = try allocator.alloc(f32, state_dim * state_dim);

        @memset(latent_states, 0.0);
        @memset(action_reps, 0.0);
        @memset(trans_model, 0.0);

        return LatentWorldModel{
            .allocator = allocator,
            .latent_states = latent_states,
            .action_representations = action_reps,
            .transition_model = trans_model,
            .state_dim = state_dim,
            .action_dim = action_dim,
            .temporal_depth = depth,
            .config = config,
        };
    }

    pub fn deinit(self: *LatentWorldModel) void {
        self.allocator.free(self.latent_states);
        self.allocator.free(self.action_representations);
        self.allocator.free(self.transition_model);
    }

    pub fn predictLatentAction(self: *LatentWorldModel, observation: []const f32, temporal_sequence: []const f32, scratch: Allocator) !LatentOutput {
        _ = temporal_sequence;

        for (1..self.temporal_depth) |t| {
            const src_start = (t - 1) * self.state_dim;
            const dst_start = t * self.state_dim;
            const src_end = src_start + self.state_dim;
            const dst_end = dst_start + self.state_dim;
            @memcpy(self.latent_states[dst_start..dst_end], self.latent_states[src_start..src_end]);
        }

        const copy_len = @min(observation.len, self.state_dim);
        @memcpy(self.latent_states[0..copy_len], observation[0..copy_len]);
        if (copy_len < self.state_dim) {
            @memset(self.latent_states[copy_len..self.state_dim], 0.0);
        }

        for (0..@min(self.temporal_depth - 1, 10)) |t| {
            const current_state = self.latent_states[t * self.state_dim..(t + 1) * self.state_dim];
            const next_state = self.latent_states[(t + 1) * self.state_dim..(t + 2) * self.state_dim];

            for (0..self.action_dim) |a| {
                var action_score: f32 = 0.0;
                for (0..@min(self.state_dim, current_state.len)) |s| {
                    action_score += current_state[s] * next_state[s % next_state.len];
                }
                self.action_representations[t * self.action_dim + a] = sigmoid(action_score);
            }
        }

        const state_repr = try scratch.alloc(f32, self.state_dim);
        @memcpy(state_repr, self.latent_states[0..self.state_dim]);

        return LatentOutput{
            .state_representation = state_repr,
            .predicted_next_state = self.latent_states[self.state_dim],
        };
    }

    pub fn consolidateLatentRepresentations(self: *LatentWorldModel, scratch: Allocator) !void {
        _ = scratch;

        const decay_factor = self.config.latent_consolidation_decay;
        const vec_width = self.config.vector_width;
        const decay_vec = @as(@Vector(vec_width, f32), @splat(decay_factor));

        const trans_count = self.transition_model.len;
        const vec_count = trans_count - (trans_count % vec_width);

        var i: usize = 0;
        while (i < vec_count) : (i += vec_width) {
            var t_vec = self.transition_model[i..][0..vec_width].*;
            t_vec = t_vec * decay_vec;
            @memcpy(self.transition_model[i..][0..vec_width], &t_vec);
        }

        while (i < trans_count) : (i += 1) {
            self.transition_model[i] *= decay_factor;
        }

        const hebbian_lr = self.config.latent_hebbian_lr;
        for (0..self.temporal_depth - 1) |t| {
            const current = self.latent_states[t * self.state_dim..(t + 1) * self.state_dim];
            const next = self.latent_states[(t + 1) * self.state_dim..(t + 2) * self.state_dim];

            for (0..self.state_dim) |i_idx| {
                for (0..self.state_dim) |j_idx| {
                    const idx = i_idx * self.state_dim + j_idx;
                    self.transition_model[idx] += hebbian_lr * current[i_idx] * next[j_idx];
                }
            }
        }
    }
};

const SchemaActiveInference = struct {
    allocator: Allocator,
    schemas: []Schema,
    free_energy: f32,
    prediction_error: f32,
    prior_beliefs: []f32,
    posterior_beliefs: []f32,
    sensory_precision: f32,
    config: *const SystemConfig,

    pub fn init(allocator: Allocator, config: *const SystemConfig, prng: *std.rand.DefaultPrng) !SchemaActiveInference {
        const num_schemas = config.schema_count;
        const belief_dim = config.schema_belief_dim;

        var schemas = try allocator.alloc(Schema, num_schemas);
        for (schemas, 0..) |*s, i| {
            s.* = try Schema.init(allocator, config, i, prng);
        }

        var priors = try allocator.alloc(f32, belief_dim);
        var posteriors = try allocator.alloc(f32, belief_dim);

        @memset(priors, 0.0);
        @memset(posteriors, 0.0);

        return SchemaActiveInference{
            .allocator = allocator,
            .schemas = schemas,
            .free_energy = 0.0,
            .prediction_error = 0.0,
            .prior_beliefs = priors,
            .posterior_beliefs = posteriors,
            .sensory_precision = config.schema_sensory_precision,
            .config = config,
        };
    }

    pub fn deinit(self: *SchemaActiveInference) void {
        for (self.schemas) |*s| {
            s.deinit();
        }
        self.allocator.free(self.schemas);
        self.allocator.free(self.prior_beliefs);
        self.allocator.free(self.posterior_beliefs);
    }

    pub fn inferSchema(self: *SchemaActiveInference, observation: []const f32, latent_state: []const f32, scratch: Allocator) !SchemaOutput {
        for (self.schemas) |*schema| {
            schema.activation = try schema.computeActivation(observation, latent_state, self.config);
        }

        try self.updateBeliefs(observation);
        self.free_energy = try self.computeFreeEnergy();

        const active = try self.getActiveSchemas(scratch);
        const coherence = self.computeSchemaCoherence();

        return SchemaOutput{
            .active_schemas = active,
            .free_energy_minimization = self.free_energy,
            .schema_coherence = coherence,
        };
    }

    fn updateBeliefs(self: *SchemaActiveInference, observation: []const f32) !void {
        @memcpy(self.prior_beliefs, self.posterior_beliefs);

        const vec_width = self.config.vector_width;
        const belief_lr = self.config.schema_belief_lr;
        const sensory_prec = self.sensory_precision;

        const lr_vec = @as(@Vector(vec_width, f32), @splat(belief_lr * sensory_prec));

        const len = self.posterior_beliefs.len;
        const vec_count = len - (len % vec_width);

        var i: usize = 0;
        while (i < vec_count) : (i += vec_width) {
            var obs_vec: @Vector(vec_width, f32) = undefined;
            for (0..vec_width) |j| {
                obs_vec[j] = if (i + j < observation.len) observation[i + j] else 0.0;
            }

            const prior_vec: @Vector(vec_width, f32) = self.prior_beliefs[i..][0..vec_width].*;
            const error_vec = obs_vec - prior_vec;
            const post_vec = prior_vec + lr_vec * error_vec;
            @memcpy(self.posterior_beliefs[i..][0..vec_width], &post_vec);
        }

        while (i < len) : (i += 1) {
            const obs = if (i < observation.len) observation[i] else 0.0;
            const prior = self.prior_beliefs[i];
            const prediction_error_i = obs - prior;
            self.posterior_beliefs[i] = prior + belief_lr * sensory_prec * prediction_error_i;
        }
    }

    fn computeFreeEnergy(self: *SchemaActiveInference) !f32 {
        var energy: f32 = 0.0;

        const kl_eps = self.config.schema_kl_epsilon;
        for (self.prior_beliefs, self.posterior_beliefs) |prior, post| {
            if (post > kl_eps and prior > kl_eps) {
                energy += post * @log(post / prior);
            }
        }

        for (self.schemas) |schema| {
            energy -= schema.activation * self.config.schema_energy_penalty;
        }

        return energy;
    }

    fn getActiveSchemas(self: *SchemaActiveInference, scratch: Allocator) ![]usize {
        var active_count: usize = 0;
        for (self.schemas) |schema| {
            if (schema.activation > self.config.schema_activation_thresh) active_count += 1;
        }

        var active = try scratch.alloc(usize, active_count);
        var idx: usize = 0;
        for (self.schemas, 0..) |schema, i| {
            if (schema.activation > self.config.schema_activation_thresh) {
                active[idx] = i;
                idx += 1;
            }
        }

        return active;
    }

    fn computeSchemaCoherence(self: *SchemaActiveInference) f32 {
        var max_activation: f32 = 0.0;
        var total_activation: f32 = 0.0;

        for (self.schemas) |schema| {
            total_activation += schema.activation;
            if (schema.activation > max_activation) {
                max_activation = schema.activation;
            }
        }

        if (total_activation > self.config.schema_kl_epsilon) {
            return max_activation / total_activation;
        }
        return 0.0;
    }

    pub fn integrateInsight(self: *SchemaActiveInference, insight: []const f32) !void {
        const target_schema_idx = self.schemas.len / 2;
        try self.schemas[target_schema_idx].integrateNewKnowledge(insight, self.config);

        self.sensory_precision *= self.config.schema_precision_update;
    }

    pub fn updateSchemaHierarchy(self: *SchemaActiveInference) !void {
        for (self.schemas) |*schema| {
            schema.consolidate(self.config);
        }
    }

    pub fn getModifiableWeights(self: *SchemaActiveInference) []f32 {
        if (self.schemas.len > 0) {
            return self.schemas[0].pattern;
        }
        return &[_]f32{};
    }
};

const Schema = struct {
    allocator: Allocator,
    id: usize,
    pattern: []f32,
    activation: f32,
    stability: f32,

    pub fn init(allocator: Allocator, config: *const SystemConfig, id: usize, prng: *std.rand.DefaultPrng) !Schema {
        const pattern_size = config.schema_pattern_size;
        var pattern = try allocator.alloc(f32, pattern_size);

        const random = prng.random();
        for (pattern) |*p| {
            p.* = random.float(f32);
        }

        return Schema{
            .allocator = allocator,
            .id = id,
            .pattern = pattern,
            .activation = 0.0,
            .stability = 0.5,
        };
    }

    pub fn deinit(self: *Schema) void {
        self.allocator.free(self.pattern);
    }

    pub fn computeActivation(self: *Schema, observation: []const f32, latent: []const f32, config: *const SystemConfig) !f32 {
        var match_score: f32 = 0.0;

        for (self.pattern, 0..) |p, i| {
            const obs = if (i < observation.len) observation[i] else 0.0;
            const lat = if (i < latent.len) latent[i] else 0.0;
            match_score += p * (obs + lat) * 0.5;
        }

        _ = config;
        return sigmoid(match_score / @as(f32, @floatFromInt(self.pattern.len)));
    }

    pub fn integrateNewKnowledge(self: *Schema, knowledge: []const f32, config: *const SystemConfig) !void {
        const learning_rate = config.schema_knowledge_lr;
        const one_minus_lr = 1.0 - learning_rate;

        const vec_width = config.vector_width;
        const len = self.pattern.len;
        const vec_count = len - (len % vec_width);

        const lr_vec = @as(@Vector(vec_width, f32), @splat(learning_rate));
        const one_minus_lr_vec = @as(@Vector(vec_width, f32), @splat(one_minus_lr));

        var i: usize = 0;
        while (i < vec_count) : (i += vec_width) {
            var p_vec = self.pattern[i..][0..vec_width].*;
            var k_vec: @Vector(vec_width, f32) = undefined;
            for (0..vec_width) |j| {
                k_vec[j] = if (i + j < knowledge.len) knowledge[i + j] else 0.0;
            }
            p_vec = p_vec * one_minus_lr_vec + k_vec * lr_vec;
            @memcpy(self.pattern[i..][0..vec_width], &p_vec);
        }

        while (i < len) : (i += 1) {
            const k = if (i < knowledge.len) knowledge[i] else 0.0;
            self.pattern[i] = self.pattern[i] * one_minus_lr + k * learning_rate;
        }

        self.stability += config.schema_stability_increment;
    }

    pub fn consolidate(self: *Schema, config: *const SystemConfig) void {
        self.stability = @min(1.0, self.stability * config.schema_stability_growth);
    }
};

const Metaplasticity = struct {
    allocator: Allocator,
    plasticity_threshold: f32,
    threshold_history: []f32,
    bcm_threshold: f32,
    activity_window: []f32,
    current_state: f32,
    config: *const SystemConfig,

    pub fn init(allocator: Allocator, config: *const SystemConfig) !Metaplasticity {
        const history_len = config.meta_history_len;
        const window_len = config.meta_window_len;

        var thresh_hist = try allocator.alloc(f32, history_len);
        var act_window = try allocator.alloc(f32, window_len);

        @memset(thresh_hist, config.meta_plasticity_init);
        @memset(act_window, 0.0);

        return Metaplasticity{
            .allocator = allocator,
            .plasticity_threshold = config.meta_plasticity_init,
            .threshold_history = thresh_hist,
            .bcm_threshold = config.meta_plasticity_init,
            .activity_window = act_window,
            .current_state = 1.0,
            .config = config,
        };
    }

    pub fn deinit(self: *Metaplasticity) void {
        self.allocator.free(self.threshold_history);
        self.allocator.free(self.activity_window);
    }

    pub fn getCurrentState(self: *Metaplasticity) f32 {
        return self.current_state;
    }

    pub fn computeHomeostaticFactor(self: *Metaplasticity) f32 {
        var avg_activity: f32 = 0.0;
        for (self.activity_window) |a| {
            avg_activity += a;
        }
        avg_activity /= @as(f32, @floatFromInt(self.activity_window.len));

        const target_activity = self.config.meta_activity_target;
        const deviation = avg_activity - target_activity;

        return 1.0 - deviation * self.config.meta_homeostatic_gain;
    }

    pub fn updatePlasticityThreshold(self: *Metaplasticity, dopamine: f32, activity: f32) !void {
        std.mem.copyBackwards(f32, self.activity_window[1..], self.activity_window[0 .. self.activity_window.len - 1]);
        self.activity_window[0] = activity;

        const avg_activity = blk: {
            var sum: f32 = 0.0;
            for (self.activity_window) |a| sum += a;
            break :blk sum / @as(f32, @floatFromInt(self.activity_window.len));
        };

        self.bcm_threshold = avg_activity * avg_activity;

        self.plasticity_threshold += self.config.meta_plasticity_lr * (dopamine - 0.5);
        self.plasticity_threshold = math.clamp(self.plasticity_threshold, self.config.meta_plasticity_clamp_low, self.config.meta_plasticity_clamp_high);

        if (activity > self.bcm_threshold) {
            self.current_state = self.config.meta_state_high;
        } else {
            self.current_state = self.config.meta_state_low;
        }

        std.mem.copyBackwards(f32, self.threshold_history[1..], self.threshold_history[0 .. self.threshold_history.len - 1]);
        self.threshold_history[0] = self.plasticity_threshold;
    }
};

const TemporalErrorAccumulator = struct {
    allocator: Allocator,
    error_buffer: []f32,
    accumulated_value: f32,
    time_independent_encoding: []f32,
    cortical_assembly: []NeuronAssembly,
    config: *const SystemConfig,

    pub fn init(allocator: Allocator, config: *const SystemConfig) !TemporalErrorAccumulator {
        const buffer_size = config.temporal_buffer_size;
        const assembly_size = config.temporal_assembly_size;

        var err_buf = try allocator.alloc(f32, buffer_size);
        var time_indep = try allocator.alloc(f32, buffer_size);
        var assemblies = try allocator.alloc(NeuronAssembly, assembly_size);

        @memset(err_buf, 0.0);
        @memset(time_indep, 0.0);

        for (assemblies) |*a| {
            a.* = NeuronAssembly.init();
        }

        return TemporalErrorAccumulator{
            .allocator = allocator,
            .error_buffer = err_buf,
            .accumulated_value = 0.0,
            .time_independent_encoding = time_indep,
            .cortical_assembly = assemblies,
            .config = config,
        };
    }

    pub fn deinit(self: *TemporalErrorAccumulator) void {
        self.allocator.free(self.error_buffer);
        self.allocator.free(self.time_independent_encoding);
        self.allocator.free(self.cortical_assembly);
    }

    pub fn accumulateError(self: *TemporalErrorAccumulator, error: f32, time_step: usize, scratch: Allocator) !void {
        _ = scratch;

        const idx = time_step % self.error_buffer.len;
        self.error_buffer[idx] = error;

        self.accumulated_value += error;

        const decay_const = self.config.temporal_decay_const;
        const assembly_sat = self.config.temporal_assembly_sat;
        const assembly_decay = self.config.temporal_assembly_decay;

        for (self.cortical_assembly, 0..) |*assembly, i| {
            const temporal_position = @as(f32, @floatFromInt((time_step + i) % self.cortical_assembly.len));
            const contribution = error * @exp(-temporal_position / decay_const);
            assembly.activity += contribution;
            assembly.activity = @min(assembly_sat, assembly.activity);
            assembly.activity *= assembly_decay;
        }

        self.time_independent_encoding[idx] = error * error;
    }

    pub fn getAccumulatedValue(self: *TemporalErrorAccumulator) f32 {
        return self.accumulated_value;
    }
};

const NeuronAssembly = struct {
    activity: f32,

    pub fn init() NeuronAssembly {
        return NeuronAssembly{
            .activity = 0.0,
        };
    }
};

const HabituationSensitization = struct {
    allocator: Allocator,
    habituation_level: f32,
    sensitization_level: f32,
    stimulus_history: []f32,
    response_magnitude: f32,
    s_r_system_state: f32,
    state_system_readiness: f32,
    config: *const SystemConfig,

    pub fn init(allocator: Allocator, config: *const SystemConfig) !HabituationSensitization {
        const history_len = config.habituation_history;

        var stim_hist = try allocator.alloc(f32, history_len);
        @memset(stim_hist, 0.0);

        return HabituationSensitization{
            .allocator = allocator,
            .habituation_level = 0.0,
            .sensitization_level = 0.0,
            .stimulus_history = stim_hist,
            .response_magnitude = 1.0,
            .s_r_system_state = config.s_r_initial,
            .state_system_readiness = config.state_readiness_initial,
            .config = config,
        };
    }

    pub fn deinit(self: *HabituationSensitization) void {
        self.allocator.free(self.stimulus_history);
    }

    pub fn processStimulus(self: *HabituationSensitization, stimulus: []const f32, intensity: f32, scratch: Allocator) !HabituationOutput {
        _ = scratch;

        const hash_value = hashInputSimd(stimulus, self.config.vector_width);

        std.mem.copyBackwards(f32, self.stimulus_history[1..], self.stimulus_history[0 .. self.stimulus_history.len - 1]);
        self.stimulus_history[0] = hash_value;

        const repetition_count = self.countRecentRepetitions();
        self.habituation_level += self.config.habituation_lr * @as(f32, @floatFromInt(repetition_count));
        self.habituation_level = @min(1.0, self.habituation_level);

        if (intensity > self.config.habituation_thresh) {
            self.sensitization_level += self.config.sensitization_lr * intensity;
            self.sensitization_level = @min(1.0, self.sensitization_level);
            self.state_system_readiness += self.config.state_readiness_increment;
        }

        self.s_r_system_state = 1.0 - self.habituation_level;

        self.response_magnitude = self.s_r_system_state * (1.0 + self.sensitization_level * self.state_system_readiness);

        self.habituation_level *= self.config.habituation_decay;
        self.sensitization_level *= self.config.sensitization_decay;

        return HabituationOutput{
            .response_magnitude = self.response_magnitude,
            .habituation_degree = self.habituation_level,
            .sensitization_degree = self.sensitization_level,
        };
    }

    fn countRecentRepetitions(self: *HabituationSensitization) usize {
        const current = self.stimulus_history[0];
        var count: usize = 0;
        const window = @min(self.config.repetition_window, self.stimulus_history.len);

        for (1..window) |i| {
            if (@abs(self.stimulus_history[i] - current) < self.config.repetition_hash_eps) {
                count += 1;
            }
        }

        return count;
    }
};

const InsightLearning = struct {
    allocator: Allocator,
    problem_representations: []ProblemState,
    insight_threshold: f32,
    incubation_time: usize,
    current_time: usize,
    config: *const SystemConfig,

    pub fn init(allocator: Allocator, config: *const SystemConfig) !InsightLearning {
        const max_problems = config.insight_problems;

        var problems = try allocator.alloc(ProblemState, max_problems);
        for (problems) |*p| {
            p.* = ProblemState.init();
        }

        return InsightLearning{
            .allocator = allocator,
            .problem_representations = problems,
            .insight_threshold = config.insight_threshold,
            .incubation_time = config.insight_incubation,
            .current_time = 0,
            .config = config,
        };
    }

    pub fn deinit(self: *InsightLearning) void {
        for (self.problem_representations) |*p| {
            p.deinit(self.allocator);
        }
        self.allocator.free(self.problem_representations);
    }

    pub fn detectAhaCondition(self: *InsightLearning, accumulated_error: f32, schema_coherence: f32) bool {
        self.current_time += 1;

        const high_error = accumulated_error > self.config.insight_error_threshold;
        const coherent_schema = schema_coherence > self.insight_threshold;
        const sufficient_incubation = (self.current_time % self.incubation_time) == 0;

        return high_error and coherent_schema and sufficient_incubation;
    }

    pub fn triggerInsight(self: *InsightLearning, active_schemas: []const usize, weights_slice: []f32, prng: *std.rand.DefaultPrng, scratch: Allocator) !InsightOutput {
        _ = weights_slice;

        const problem_idx = self.current_time % self.problem_representations.len;
        var problem = &self.problem_representations[problem_idx];

        const solution = try scratch.alloc(f32, self.config.insight_solution_dim);

        const random = prng.random();
        const annealing_temp = self.config.insight_annealing_temp;

        for (solution, 0..) |*s, i| {
            var combined: f32 = 0.0;
            for (active_schemas) |schema_id| {
                combined += @as(f32, @floatFromInt(schema_id)) * @as(f32, @floatFromInt(i + 1));
            }

            const noise = (random.float(f32) - 0.5) * annealing_temp;
            s.* = sigmoid(combined / 100.0 + noise);
